  const goals = board('Objetivos UX y principios de diseño', [dH('Objetivos UX'), dBul(['Que cualquier rol entienda qué puede hacer desde su primer ingreso, sin capacitación extensa (navegación por rol, una acción primaria por vista).', 'Registrar un curso completo sin errores de estándar: validación en línea, contadores, cálculo automático, guardado progresivo (OBJ-02).', 'Hacer visible el estado de cada curso y su historial en todo momento (OBJ-04).', 'Respetar permisos: no mostrar acciones que el rol no puede ejecutar (RF-008, OBJ-03).', 'Accesible (WCAG 2.2 AA) y bilingüe ES/EN (RNF-034 a 040, RF-044).']),
  dH('Principios'), dBul(['Claridad antes que decoración: Modern Enterprise SaaS + minimalismo; neumorfismo suave solo en KPI/resúmenes.', 'Estado siempre explícito: icono + texto + color, nunca solo color.', 'Prevenir y recuperar: errores junto al campo, foco al primero, nada se pierde (RNF-023/024).', 'Distinguir guardar de enviar: "Guardar borrador" (formatos/límites) vs "Listo para enviar" (validación completa).', 'Consistencia por sistema: todo se compone del Design System (04).', 'Marca con respeto: logo oficial vectorial, azules institucionales como base, secundarios solo puntuales.'])]);
  const scope = board('Alcance', [dH('Incluido (44 historias RF-001 a RF-044)'), dBul(['Autenticación Google institucional y correo/contraseña; control de acceso por rol y escuela.', 'Usuarios: registro, rol único, listado, edición, eliminación, búsqueda.', 'Catálogos maestros (10) con búsqueda, eliminación controlada y carga CSV (Áreas SFIA, Temáticas, Casas certificadoras).', 'Cursos: creación progresiva en 8 secciones, adjuntos Word/PDF, asistencia Gemini en 4 campos.', 'Flujo de aprobación: envío, bandeja, código, aprobación, En producción, Inactivo.', 'Avisos por correo y notificación de escritorio; consulta y búsqueda; reportes de producción e histórico; interfaz ES/EN.']),
  dH('Fuera de alcance (ERS §1.2)'), dBul(['Estudiantes y matrículas · integración automática con Power Campus · creación dinámica de roles · eliminación física de cursos · exportación de reportes · recuperación de contraseña, MFA y cierre de sesión.'])]);
  const refs = board('Documentación de referencia y prioridad', [dTable([['Prioridad', 120], ['Documento', 420], ['Uso en el diseño', 900]], [['1', 'ERS v1.1 (12 oct 2026)', 'Fuente principal: requerimientos, roles, reglas de negocio (RN-01 a RN-29), estados, campos (Apéndice B), catálogos (Apéndice C), pendientes (Apéndice E).'], ['2', 'Documento de Diseño · Iteración 1', 'Arquitectura de vistas, estructura de formularios, mensajes de validación, casos de prueba. Donde contradice a la ERS v1.1 prevalece la ERS (ver 09 · Contradicciones).'], ['3', 'Libro de Marca CENFOTEC 2022', 'Logotipo (vector extraído del PDF), colores primarios y secundarios, tipografías DIN Alternate / Circular Std (sustituidas por Barlow / Figtree).']]),
  dH('Organización de este archivo'), dP('Plan Starter de Figma = máximo 3 páginas. Las 10 secciones pedidas se conservan como Sections: Página 1 → 00, 01, 02 · Página 2 → 03 Wireframes, 04 Design System · Página 3 → 05 Desktop, 06 Tablet, 07 Mobile, 08 Prototipo, 09 Handoff. Al pasar a un plan con más páginas, cada Section se mueve a su propia página sin rehacer nada.')]);
  return [cover, desc, goals, scope, refs];
