function flowBoard(title, refs, main, alts) {
  const kids = []; main.forEach((n, i) => { kids.push(fNode(n[0], n[1], n[2])); if (i < main.length - 1) kids.push(I('arrow-right', 24, 'text/secondary')); });
  return board(title, [tag(refs, 'Info'), F({ n: 'Main path', d: 'H', g: 10, cx: 'CENTER', wrap: true, w: 3300, cg: 24 }, kids), overline('Ramas y estados alternativos'), dBul(alts, 3300)], 3400);
}
