function compInventory() {
  const rows = [];
  for (const [n, c] of Object.entries(S.cn)) {
    if (n.startsWith('icon/') || n.startsWith('brand/')) continue;
    let variants = c.type === 'COMPONENT_SET' ? c.children.length : 1; let props = '';
    try { props = Object.entries(c.componentPropertyDefinitions || {}).map(([k, d]) => k.split('#')[0] + (d.type === 'VARIANT' ? ' (' + d.variantOptions.join('/') + ')' : '')).join(' · '); } catch (e) { props = '—'; }
    rows.push([n, String(variants), props.slice(0, 160) || '—', (c.description || '').slice(0, 150)]);
  }
  rows.push(['Iconos', String(Object.keys(S.cn).filter(k => k.startsWith('icon/')).length), 'INSTANCE_SWAP en Button, Icon Button, Tag, KPI, Nav Item…', 'Lineales 24 px estilo Lucide + G de Google.']);
  rows.push(['Logotipos', '2', 'Color · Blanco (1 tinta)', 'Vector oficial extraído del Libro de Marca.']);
  return dTable([['Componente', 260], ['Variantes', 100], ['Propiedades', 760], ['Uso', 640]], rows, 'Inventario de componentes');
}
