async function buildDocs() {
  let n = 0;
  const p0 = await pageAt(0);
  for (const [name, fn, per] of [['00 — Project Overview', overviewBoards, 2], ['01 — Information Architecture', iaBoards, 1], ['02 — User Flows', flowBoards, 1]]) {
    const sec = section(p0, name, 0, 0, 4000, 2000); clearSection(sec);
    const boards = await safe('Docs ' + name, async () => fn()) || []; placeBoards(sec, boards, per); fit(sec); n += boards.length;
  }
  stackSections(p0, ['00 — Project Overview', '01 — Information Architecture', '02 — User Flows']);
  const p2 = await pageAt(2);
  const sec = section(p2, '09 — UX Documentation & Handoff', 0, 0, 4000, 2000); clearSection(sec);
  const boards = await safe('Docs 09', async () => handoffBoards()) || []; placeBoards(sec, boards, 2); fit(sec); n += boards.length;
  return n;
}
function stackSections(page, order, gap = 600) {
  let y = 0;
  for (const name of order) { const s = page.children.find(n => n.type === 'SECTION' && n.name === name); if (!s) continue; s.x = 0; s.y = y; y += s.height + gap; }
}

